INSERT INTO "data"."data_tbl_class" ("id", "apt_agility", "apt_energy", "apt_intelligence", "apt_stamina", "apt_strength", "att_agility", "att_energy", "att_intelligence", "att_stamina", "att_strength", "bright_code", "class_description", "color_code_female1", "color_code_female2", "color_code_female3", "color_code_male1", "color_code_male2", "color_code_male3", "description_female", "description_male", "icon_code_female", "icon_code_male", "img_code_female", "img_code_male", "large_img_female", "large_img_male", "name", "res_code_female", "res_code_female2", "res_code_male", "res_code_male2", "school_description", "start_item", "start_skill") VALUES
	(1, 2100, 1600, 1500, 2500, 2300, 10, 5, 5, 15, 15, 0, 'Đặc tính: |Phòng ngự tuyệt đối, sinh mệnh siêu cao, xả thân tấn công |Giới thiệu: |Chiến Binh chính là tấm khiên lớn của toàn đội. Họ có lực tấn công và phòng thủ vật lý cực mạnh so với các tộc nhân khác. Họ thường sử dụng đại chùy cùng khiên do chính mình chế tạo để tạo thành tấm chắn bảo vệ đồng đội phía sau.', 0, -100, 150, 0, -100, 150, 'Nàng là một cô gái cần cù và lương thiện. Đối với cô ấy việc tham gia khám phá thế giới hoang dã, quan sát các hiện tượng trong cuộc sống là một điều hết sức thú vị. Từ những điểm nhỏ trong cuộc sống nàng đã phát hiện ra làm thế nào mà người với người có thể sống chung, để từ đó cô ấy có thể tự mình tìm ra phương thức phát triển cho bản thân.', 'Một chàng trai trung thực và chân thật, luôn tin tưởng rằng thông qua nỗ lực của chính mình có thể mang lại cho mọi người xung quanh một cuộc sống đầy đủ và hạnh phúc. ', 3050080000001, 3050070000001, 3050080100001, 3050070100001, 4050080200001, 4050070200001, 'Chiến Binh', 2050080000001, 2050080000011, 2050070000001, 2050070000011, 'Bàn Địa Tộc chú trọng việc bồi dưỡng kỹ năng phán đoán cùng nghiên cứu thổ mộc nên được xưng là Thổ Mộc Công Trình Sư. Nơi đây các đệ tử mang tri thức thổ mộc công trình vận dụng vào cuộc sống thường ngày, mỗi vị đệ tử đều là người có lý luận cơ sở vững chắc  thao tác tay nghề vững vàng. Tại quá trình thao tác ma luyện, Bàn Địa đệ tử từ từ hình thành nên phong cách ứng xử đặc trưng. Loại phong cách này cũng dần bị mang đến các cuộc chiến đấu.', NULL, '1010|1086'),
	(2, 2200, 2500, 2200, 1600, 1500, 10, 12, 12, 8, 8, 0, 'Đặc tính: |Khống chế, nghịch chuyển sức mạnh, tấn công ma pháp| Giới thiệu: | Họ nắm giữ trong tay linh hồn âm nhạc, sử dụng đàn violon để khống chế đối thủ. Với đôi bàn tay kỳ diệu, khi gảy lên những âm điệu có thể làm mê hoặc lòng người. Tại chiến trường họ là một điều phối viên, có thể khiến cho cuộc chiến vốn gian nan trở nên đơn giản một cách dị thường.', 0, -100, 150, 0, -100, 150, 'Nàng là một người lãng mạn, yêu thích violin, làm việc nhanh nhẹn gọn gàng và đầy trí tuệ. Mục tiêu chính của nàng là trở thành một bậc thầy diễn tấu và sáng tạo ra một loại nhạc khí mới của mình', 'Tuy tính cách có chút trầm mặc nhưng luôn quan tâm đến những người yếu đuối và vì họ mà cất lên tiếng hát. Là một nghệ sĩ chân chính nên mọi hành động luôn có vẻ ung dung tạo nên cảm giác siêu phàm thoát tục.', 3050080000006, 3050070000006, 3050080100002, 3050070100002, 4050080200002, 4050070200002, 'Nhạc Công', 2050080000006, 2050080000016, 2050070000006, 2050070000016, 'Liêu Vân tộc, đệ nhất gia tộc âm nhạc tại Đông Huyền, mỗi vị đệ tử đều có thiên phú xuất sắc về nghệ thuật. Họ đưa âm nhạc thăng hoa đến cảnh giới cao nhất, thậm chí mỗi âm thanh đều có ẩn chứa sự huyền bí vô tận. Từ âm nhạc có thể tìm hiểu được cuộc sống, đệ tử của Liêu Vân tính cách đều hết sức trong sáng, đối với mơ ước tương lai đều ẩn chứa rất nhỏ sự đa sầu thiện cảm, khiến cho mọi người có thể cảm nhận phần nào cuộc sống của họ.', NULL, '2002|2012'),
	(3, 1500, 2400, 2400, 1900, 1800, 7, 14, 13, 7, 9, 0, 'Đặc tính: |Tăng cường sức mạnh, tịnh hóa, hồi phục năng lượng|Giới thiệu: |Danh y là một người quan trọng của tổ đội. Họ nắm giữ trong tay kỹ thuật trị liệu, hồi phục.  Một danh y bình tĩnh thì sẽ nắm trong tay phương pháp trị liệu mạnh mẽ nhất.', 0, -100, 150, 0, -100, 150, 'Nàng là một người rất yêu thích các câu chuyện cổ tích, tính cách ngây thơ. Khi gặp một vấn đề phức tạp thì khuôn mặt sẽ biểu hiện rất đáng yêu. Là một người có thể sử dụng một cách thuần thục trị liệu thuật, vì vậy đây là một nhân tố quan trọng trong một tổ đội.', 'Được xưng là chàng trai hoàn mỹ nhất Đông Huyền. Với tài năng tuyệt vời về chữa trị, nụ cười luôn nở trên môi được mọi người ví như "Nụ cười thiên sứ", tại Đông Huyền đã khiến vô số cô gái say mê.', 3050080000002, 3050070000002, 3050080100003, 3050070100003, 4050080200003, 4050070200003, 'Danh Y', 2050080000002, 2050080000012, 2050070000002, 2050070000012, 'Linh Vũ tộc. Gia tộc lấy sự ưu nhã, lễ nghi làm tôn chỉ bồi dưỡng tộc nhân. Cho nên, mỗi đệ tử của tộc này đều nói chuyện rất ôn hòa, cử chỉ khiêm tốn, lễ độ đúng mực. Cuộc sống như vậy chắc chắn sẽ có sự đồng cảm nhất định đối với thơ ca. Trong quá trình chiến đấu, chỉ cần chứng kiến thần thái luôn bình yên tự nhiên của họ thì mỗi người đều cảm thấy yên lòng.', NULL, '1892|1903'),
	(4, 1700, 2300, 2700, 1700, 1600, 10, 12, 15, 5, 8, 0, 'Đặc tính: |Tấn công tầm xa, sát thương nhiều mục tiêu, tấn công ma pháp siêu cấp|Giới thiệu: |Xạ Thủ chính là thành viên có năng lực công kích pháp thuật cực mạnh. Họ sử dụng hỏa lực mạnh mẽ để tiến hành áp chế toàn diện thế cục cuộc chiến. Trước mặt Xạ Thủ, khoảng cách và số lượng kẻ thù hoàn toàn không chút ý nghĩa, với phát súng đầu tiên họ có thể giải quyết xong mọi chuyện @_@.', 0, -100, 150, 0, -100, 150, 'Một người đam mê khoa học, luôn chú trọng vào nghiên cứu súng đạn, cơ giới. Mỗi ngày, nàng dành rất nhiều thời gian tạo phòng thí nghiệm để tạo ra những loại vũ khí mới. Trong khái niệm của nàng, việc nói chuyện là "nhàm chán" nên một ngày nói không quá 10 câu và luôn ưu tiên cho hiệu suất công việc ... Đây chính là một Băng Tâm Mỹ Nhân', 'Cuồng nhân say mê khoa học và sưu tầm các mô hình cơ giới, không thể nghi ngờ đây là một người "hơi bị" khác thường tại Đông Huyền nhưng lại mang trong mình số đào hoa. Bình thường nghiêm túc trầm mặc, nhưng một khi gặp được vấn đề cảm thấy hứng thú thì lập tức sẽ khác hẳn.', 3050080000005, 3050070000005, 3050080100005, 3050070100005, 4050080200005, 4050070200005, 'Xạ Thủ', 2050080000005, 2050080000015, 2050070000005, 2050070000015, 'Thiên Khung Tộc,  luôn theo đuổi các bí ẩn huyễn tưởng, nên tập trung nguyên cứu, tìm tòi vũ trụ huyền bí. Các đệ tử của tộc này thường lấy sự tỉnh táo linh mẫn để nắm bắt và giải quyết các vấn đề. Là những người theo đuổi mộng tưởng, cực kỳ kiên định và tín niệm, điều này đã khiến họ dù trong thời khắc khó khăn nhất vẫn luôn duy trì lý trí, lâm nguy bất loạn.', NULL, '1789|1819'),
	(5, 2000, 2000, 2000, 2000, 2000, 10, 8, 10, 11, 11, 0, 'Đặc tính: |Bắt pet với tốc độ siêu hạng, tấn công vật lý|Giới thiệu: |Thợ săn là một nhân tộc có chỉ số sinh lực cao nhất. Dựa vào đôi tay xuất sắc với kỹ năng thuần hóa Pet và thân thủ nhanh nhẹn, họ có thể dễ dàng đột phá thế trận của đối thủ. Trong tổ đội, họ chính là mũi đao đột kích, nếu quên đi sự tồn tại của một thợ săn trong đội ngũ thì thường sẽ đi đến sự thất bại.', 0, -100, 150, 0, -100, 150, 'Là một người luôn chú trọng vào việc thuần dưỡng và bảo vệ thú cưng, Trong cuộc chiến, nàng thường dựa vào sức mạnh của mình để giành lợi thế, luôn giành chiến thắng vì thú cưng đáng yêu của mình.', 'Huấn luyện sư chuyên thuần hóa thú dữ đầu tiên tại Vô Ưu đại lục. Với tính cách kiên định và hiếu động, trong chiến đấu luôn bộc lộ hết sức ngoan cường, luôn cùng Thú Cưng tiến hành những cuộc tập luyện khắc nghiệt trong môi trường hoang dã vì mục tiêu trở thành huấn luyện sư đệ nhất đại lục.', 3050080000003, 3050070000003, 3050080100004, 3050070100004, 4050080200004, 4050070200004, 'Thợ Săn', 2050080000003, 2050080000013, 2050070000003, 2050070000013, 'Huyền Lâm tộc, gia tộc sử dụng các loại thể dục vận động để phát triển nhân loại tiềm lực. Trong quá trình tìm tòi đã sáng tạo nên một bộ kỹ xảo chiến đấu đặc thù bao hàm các nguyên lý vận động phát triển toàn thể. Huyền Lâm đệ tử đều sở hữu siêu cường vận động lực lượng và thiên phú hơn người. Với khả năng lĩnh ngộ dẫn lực cùng khống chế lực tinh xảo, khiến họ trong chớp mắt có thể lĩnh ngộ, tìm được sơ hở, một kích phá địch.', NULL, '2114|2134'),
	(6, 2200, 1600, 1500, 2200, 2500, 12, 8, 8, 10, 12, 0, 'Đặc tính: |Tấn công liên tục nhiều mục tiêu, tấn công vật lý siêu cấp|Giới thiệu: |Hiệp Sĩ, người kế thừa tinh hoa của võ thuật, là tấm chắn đầy cơ bắp của toàn đội. Với nhiệt huyết sôi trào, trong chiến đấu họ thường xông lên tuyến đầu.', 0, -100, 150, 0, -100, 150, 'Là một người đam mê chiến đấu, nàng thường lộ ra khí phách hào sảng của nam tử, luôn bảo vệ kẻ yếu can thiệp vào chuyện bất bình. Mặc dù vậy, nội tâm của nàng luôn hy vọng có người sẽ chú ý bảo vệ mình. Lợi thế của nàng là thân pháp nhanh nhẹn, tinh xảo.', 'Khí phách hào hùng pha chút bướng bỉnh, tuy nhiên trải qua quá trình rèn luyện gian khổ thì ngày càng tiếp cận đến phong thái của tuyệt thế cao thủ, thấy chuyện bất bình chẳng bỏ qua, thường làm việc trượng nghĩa giúp đỡ mọi người.', 3050080000004, 3050070000004, 3050080100006, 3050070100006, 4050080200006, 4050070200006, 'Hiệp Sĩ', 2050080000004, 2050080000014, 2050070000004, 2050070000014, 'Lưu Hỏa tộc, thánh địa truyền thuyết nơi luôn sản sinh các huyền thoại, thu nhận truyền nhân về sử dụng đao kiếm. Bất kỳ ai sùng bái võ đạo đều ước mơ được gia nhập Lưu Hỏa tộc để được khai trí , bước trên con đường hành hiệp trượng nghĩa. Một khi tiến vào Lưu Hỏa tộc, mọi người tự ý thức về trách nhiệm bản thân, phải tự rèn luyện, chiến đấu và đổ máu mới có thành tựu.', NULL, '2215|2225');


